import{_ as o}from"./chunks/28-overview.CM7REA8J.js";import{_ as t,c as a,o as r,a2 as s}from"./chunks/framework.jqDK1qTK.js";const f=JSON.parse('{"title":"0028 Self Hosted Shoot Clusters","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0028-self-hosted-shoot-clusters","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0028-self-hosted-shoot-clusters/README.md","to":"README.md"},"title":"0028 Self Hosted Shoot Clusters","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0028-self-hosted-shoot-clusters/index.md","filePath":"docs/proposals/0028-self-hosted-shoot-clusters/index.md","lastUpdated":null}'),n={name:"docs/proposals/0028-self-hosted-shoot-clusters/index.md"};function i(d,e,l,c,h,u){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="gep-0028-self-hosted-shoot-clusters" tabindex="-1">GEP-0028: Self-Hosted Shoot Clusters <a class="header-anchor" href="#gep-0028-self-hosted-shoot-clusters" aria-label="Permalink to &quot;GEP-0028: Self-Hosted Shoot Clusters&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gep-0028-self-hosted-shoot-clusters">GEP-0028: Self-Hosted Shoot Clusters</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#table-of-contents">Table of Contents</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#goals">Goals</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#non-goals">Non-Goals</a></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#proposal">Proposal</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#prerequisites">Prerequisites</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#commands">Commands</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-discover"><code>gardenadm discover</code></a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-init"><code>gardenadm init</code></a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#problems--solutions">Problems &amp; Solutions</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#faking-a-kubernetes-api">Faking a Kubernetes API</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#host-network-vs-pod-network">Host Network vs. Pod Network</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#dealing-with-webhooks-for-control-plane-components">Dealing with Webhooks for Control Plane Components</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#etcd-management-via-etcd-druid"><code>etcd</code> Management via <code>etcd-druid</code></a></li></ul></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-token"><code>gardenadm token</code></a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-join"><code>gardenadm join</code></a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-connect"><code>gardenadm connect</code></a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-version"><code>gardenadm version</code></a></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#shoot-api"><code>Shoot</code> API</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#scenarios">Scenarios</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#unmanaged-infrastructure">Unmanaged Infrastructure</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#managed-infrastructure">Managed Infrastructure</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-bootstrap"><code>gardenadm bootstrap</code></a></li></ul></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#disaster-recovery">Disaster Recovery</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#single-node-failure">Single-Node Failure</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#multi-node-failure">Multi-Node Failure</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#data-center-failure">Data Center Failure</a></li></ul></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#future-work">Future Work</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#self-hosted-shoot-clusters-for-end-users">Self-Hosted Shoot Clusters for End-Users</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#network-connectivity-to-garden-cluster">Network Connectivity to Garden Cluster</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#changes-to-shoot-components">Changes to Shoot Components</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#air-gapped-gardener-landscapes">Air-Gapped Gardener Landscapes</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#scaling-the-control-plane-of-self-hosted-shoot-clusters">Scaling the Control Plane of Self-Hosted Shoot Clusters</a></li></ul></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#alternatives">Alternatives</a><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#using-existing-tools">Using Existing Tools</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#using-existing-services">Using Existing Services</a></li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#using-existing-gardener">Using Existing Gardener</a></li></ul></li></ul></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Gardener ships with functionality that would allow the creation of &quot;self-hosted&quot; shoot clusters. Such &quot;self-hosted&quot; clusters would be regular shoot clusters with the main difference that their control plane runs on dedicated nodes within the cluster itself (instead of a seed cluster which typically resides in another infrastructure account and network domain). This deployment model is known as the typical/standard Kubernetes deployment model, while Gardener&#39;s regular shoot clusters today follow the &quot;Kubeception&quot; deployment model.</p><p><img src="'+o+'" alt="Overview"></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>This shall not be a drop-in replacement for <a href="https://k3s.io" target="_blank" rel="noreferrer"><code>k3s</code></a> or <a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm" target="_blank" rel="noreferrer"><code>kubeadm</code></a> (that would be too far away from Gardener&#39;s mission statement, TCO goals, and current implementation), but we want to offer this new type of shoot clusters as a separate flavor to enable on-prem use-cases that cannot be served with Gardener today. By allowing the remote management through Gardener, &quot;self-hosted&quot; clusters will meet our mission statement (e.g., in regard to low TCO) while operating without the need of a seed cluster.</p></div><p>Such self-hosted shoot clusters are meant to operate autonomously, but not to exist completely independently of Gardener. Hence, after initial creation, they shall be connected to an existing Gardener system such that the established cluster management functionality via the <code>Shoot</code> API can be applied.</p><p>Furthermore, self-hosted shoot clusters are not considered a replacement or alternative for regular shoot clusters. They should be only used for special use-cases or requirements as their creation time will be longer and their costs will be higher. In this light, a high cluster creation/deletion churn rate is neither expected nor in scope.</p><p>Gardener&#39;s APIs and cluster topology are defined in a way such that seed clusters are a separate &quot;security domain&quot; and not accessible to end-users. With self-hosted shoot clusters, seed clusters do not exist anymore, hence, running a <code>gardenlet</code> and certain seed system components (like extensions) within the end-user&#39;s infrastructure requires rework and adaptation of some of today&#39;s concepts. As operating self-hosted shoot clusters is a challenge big enough on its own, we&#39;ll start with focusing only on how Gardener operators can create and connect self-hosted shoot clusters. Allowing &quot;untrusted&quot; end-users to create such clusters is out of scope of this GEP and considered to be future work (<a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#self-hosted-shoot-clusters-for-end-users">see below</a>).</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Gardener is a great tool for creating and managing clusters with very low TCO. Part of this success is its architecture, i.e., running control planes in seed clusters under joint supervision by Gardener and Kubernetes (a.k.a. Kubeception deployment model).</p><p>However, there is sufficient pull to also find a way to create self-hosted shoot clusters using Gardener (e.g., for the edge or for temporarily air-gapped scenarios) where the control plane must run side-by-side and cannot run in seed clusters. We want to establish Gardener in (new) environments where clusters cannot run their control plane &quot;somewhere else&quot;, but where it needs to be co-located with the worker nodes, e.g., to avoid costly or exposed network traffic, firewall the entire cluster off, rely on the control plane while the cluster is air-gapped/has no internet access, generally avoid runtime dependencies, fulfill compliance obligations, etc.</p><p>In addition, Gardener itself requires to run in a conformant Kubernetes cluster satisfying the <a href="https://github.com/gardener/gardener/tree/master/docs/usage/shoot-operations/supported_k8s_versions.md#garden-clusters" target="_blank" rel="noreferrer">minimum Kubernetes version requirements</a>, but so far there was no way of setting up or managing this initial cluster via Gardener itself. It was always required to leverage third-party tools or services, which is not only inconvenient but also somewhat paradoxical, given that Gardener itself already is a tool for managing Kubernetes clusters. Augmenting Gardener&#39;s capability to also manage the initial cluster will help to reduce operational complexity and enable new use-cases and scenarios.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Creation of self-hosted shoot clusters running dedicated nodes for control plane components</li><li>Maximize re-use of existing code/functionality to prevent re-inventing the wheel</li><li>Enable cluster management and upgrades via the <code>Shoot</code> API of an existing Gardener</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><ul><li>Creation/deletion of self-hosted shoot clusters with high churn rates and convenience compared to regular shoot clusters</li><li>Allow end-users to create self-hosted shoot clusters and connect them to a Gardener system - this aspect will be covered in a future GEP after this one has been implemented</li><li>Provide functionality to create self-hosted shoot clusters via the API of an existing Gardener system</li><li>Support day-2 operations without connecting the cluster to an existing Gardener system</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>In short, the basic idea is to develop a new command line tool that is going to be shipped with every Gardener release, <code>gardenadm</code>, which can be used to bootstrap a self-hosted shoot cluster.</p><img src="https://github.com/gardener/gardener/raw/master/logo/gardenadm-large.png" alt="gardenadm" width="100"><p>In order to reduce cognitive load, we&#39;ll align the user experience of this new tool with what <a href="https://kubernetes.io/docs/reference/setup-tools/kubeadm/" target="_blank" rel="noreferrer"><code>kubeadm</code></a> provides (note that <code>gardenadm</code> is not meant to replace <code>kubeadm</code> - we just want to reduce the entry barrier for people already familiar with <code>kubeadm</code>, <a href="https://github.com/gardener/gardener/tree/master/README.md#gardener" target="_blank" rel="noreferrer">similar to how we have aligned the Gardener architecture with Kubernetes concepts</a>). After a cluster has been set up with <code>gardenadm</code>, the next step is to deploy a stripped-down version of <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/gardenlet.md" target="_blank" rel="noreferrer"><code>gardenlet</code></a> into it. This <code>gardenlet</code> has coordinates for an existing Gardener system it can connect to such that it can register the <code>Shoot</code> resource (similar to how it registers the <code>Seed</code> resource today when running in a seed cluster). Any day-2 operations like updates or upgrades will be performed by the <code>gardenlet</code> and via the <code>Shoot</code> API. As a consequence, there will be no command in <code>gardenadm</code> similar to <a href="https://kubernetes.io/docs/reference/setup-tools/kubeadm/kubeadm-upgrade/" target="_blank" rel="noreferrer"><code>kubeadm upgrade</code></a>. It is explicitly out of scope to support cluster management without a <code>gardenlet</code> connected to a Gardener system (see <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-connect"><code>gardenadm connect</code> section</a> for more details).</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Similar to <a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/install-kubeadm/#before-you-begin" target="_blank" rel="noreferrer"><code>kubeadm</code>&#39;s prerequisites</a>, <code>gardenadm</code> will assume that the following requirements are met for the machines:</p><ul><li>One or more compatible Linux hosts.</li><li>Sufficient CPU and RAM (to be specified more concretely later).</li><li>Full network connectivity between all machines in the cluster (public or private network is fine).</li><li><a href="https://kubernetes.io/docs/reference/networking/ports-and-protocols/" target="_blank" rel="noreferrer">Certain ports</a> must be open.</li><li><a href="https://www.freedesktop.org/wiki/Software/systemd/" target="_blank" rel="noreferrer">systemd</a>, <a href="https://containerd.io/" target="_blank" rel="noreferrer">containerd</a>, and its <a href="https://github.com/projectatomic/containerd/blob/master/docs/cli.md/" target="_blank" rel="noreferrer">ctr (client CLI)</a> must be pre-installed.</li></ul><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><p><code>gardenadm</code> will have the following commands:</p><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-discover"><code>gardenadm discover</code></a> to discover the configuration of the Gardener system the self-hosted shoot cluster shall be connected to later.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-init"><code>gardenadm init</code></a> to bootstrap a first control plane node.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-token"><code>gardenadm token</code></a> to manage bootstrap and discovery tokens for <code>gardenadm join</code>.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-join"><code>gardenadm join</code></a> to bootstrap further control plane nodes, or to bootstrap worker nodes and join them to the cluster.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-connect"><code>gardenadm connect</code></a> to deploy a <code>gardenlet</code> for further cluster management.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-version"><code>gardenadm version</code></a> to print the <code>gardenadm</code> version.</li></ul><p>The general flow for bootstrapping a self-hosted shoot cluster will be as follows:</p><ol><li>The user installs <code>gardenadm</code> on the first control plane node and runs <code>gardenadm discover</code>. This will download relevant configuration from the Gardener system the self-hosted shoot cluster shall be later connected to (e.g., <code>Controller{Registration,Deployment}</code>s, <code>CloudProfile</code>s, etc.). If there is no existing Gardener system yet, the needed configuration must be provided manually.</li><li>The downloaded configuration and a <code>Shoot</code> manifest are provided to the <code>gardenadm init</code> command. This will bootstrap the first control plane node.</li><li>Optionally, additional control plane nodes can be joined. In order to do so, the user runs <code>gardenadm token generate</code> which generates a random bootstrap token, and then <code>gardenadm token create &lt;token&gt;</code> which creates it on the server. Now connected to the new node that shall be joined, the user runs the <code>gardenadm join</code> command which bootstraps another control plane node.</li><li>Optionally, worker nodes can be joined. The flow is the same - a bootstrap token must be generated and created, and then <code>gardenadm join</code> must be executed to bootstrap the worker node.</li><li>Once above steps are completed, the user runs <code>gardenadm connect</code> to deploy a <code>gardenlet</code> into the cluster which connects to an existing Gardener system for further cluster management.</li></ol><p>A more detailed description of the commands is following.</p><h4 id="gardenadm-discover" tabindex="-1"><code>gardenadm discover</code> <a class="header-anchor" href="#gardenadm-discover" aria-label="Permalink to &quot;`gardenadm discover`&quot;">​</a></h4><p>This command takes a kubeconfig to an existing Gardener system, and a <code>Shoot</code> manifest. It downloads the required <code>CloudProfile</code>, <code>ControllerRegistration</code> and <code>ControllerDeployment</code> resources and stores them locally for usage of other <code>gardenadm</code> commands. This simplifies the crafting of these documents, and it also ensures that the configuration and versions used for the bootstrapping of the self-hosted shoot cluster fit to the configuration later found in the connected Gardener system.</p><h4 id="gardenadm-init" tabindex="-1"><code>gardenadm init</code> <a class="header-anchor" href="#gardenadm-init" aria-label="Permalink to &quot;`gardenadm init`&quot;">​</a></h4><p>This command bootstraps the first control plane node of the self-hosted shoot cluster. The configuration is specified via separate files. It needs a <code>Shoot</code> manifest and some additional configuration files, which usually reside in the garden cluster, e.g., a <code>CloudProfile</code> (best downloaded with <code>gardenadm discover</code>). For the initial cluster Gardener bootstrapping use-case however, these won&#39;t come from a pre-existing garden cluster as it doesn&#39;t exist yet. They can then be provided locally (that&#39;s why <code>gardenadm discover</code> and <code>gardenadm init</code> are separate commands), reflecting the to-be-deployed Gardener system later.</p><p>The high-level steps executed by the command are as follows:</p><ol><li>Generate certificate authorities, certificates and keys using the <a href="https://github.com/gardener/gardener/tree/master/docs/development/secrets_management.md" target="_blank" rel="noreferrer">secrets manager</a>.</li><li>Generate <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/resources/operatingsystemconfig.md" target="_blank" rel="noreferrer"><code>OperatingSystemConfig</code> resource</a> (in memory) containing <code>systemd</code> units and files. This includes the files for the minimal standard Kubernetes control plane, i.e., <code>kubelet</code>, <code>etcd</code>, <code>kube-apiserver</code>, <code>kube-controller-manager</code>, and <code>kube-scheduler</code>. Also, it should be OS-agnostic (since there is no operating system config extension running anywhere yet).</li><li>Reconcile the <code>OperatingSystemConfig</code> resource using the controller logic of <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/node-agent.md" target="_blank" rel="noreferrer"><code>gardener-node-agent</code></a>.</li><li><code>kubelet</code> starts and runs the static pods for the minimal standard Kubernetes control plane (<code>etcd</code>, <code>kube-apiserver</code>, <code>kube-controller-manager</code> and <code>kube-scheduler</code>).</li><li>Deploy <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/resource-manager.md" target="_blank" rel="noreferrer"><code>gardener-resource-manager</code></a> in <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#host-network-vs-pod-network">host network mode</a> into the <code>kube-system</code> namespace.</li><li>Apply the corresponding provider and networking extensions in <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#host-network-vs-pod-network">host network mode</a>.</li><li>Deploy <code>kube-proxy</code> and CoreDNS for service routing and domain name resolution.</li><li>Create a <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/resources/network.md" target="_blank" rel="noreferrer"><code>Network</code> resource</a> and apply it to generate <code>ManagedResource</code> associated with the pod network.</li><li>Apply the corresponding provider and networking extensions in <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#host-network-vs-pod-network">pod network mode</a>. Also deploy the operating system config extensions.</li><li>Redeploy <code>gardener-resource-manager</code> in <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#host-network-vs-pod-network">pod network mode</a>.</li><li>Create the <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/resources/operatingsystemconfig.md" target="_blank" rel="noreferrer"><code>OperatingSystemConfig</code> resource</a> now in the cluster and activate the <code>gardener-node-agent</code> process via its <code>systemd</code> unit.</li><li>Apply <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/resources/controlplane.md" target="_blank" rel="noreferrer"><code>ControlPlane</code> resource</a>.</li></ol><h5 id="problems-solutions" tabindex="-1">Problems &amp; Solutions <a class="header-anchor" href="#problems-solutions" aria-label="Permalink to &quot;Problems &amp; Solutions&quot;">​</a></h5><p>As we intend to re-use code as much as possible, we need to jump through some hoops to make this work.</p><h6 id="faking-a-kubernetes-api" tabindex="-1">Faking a Kubernetes API <a class="header-anchor" href="#faking-a-kubernetes-api" aria-label="Permalink to &quot;Faking a Kubernetes API&quot;">​</a></h6><p>Most of the Gardener code base assumes an always existing garden cluster or the API server of a seed cluster, which might not be available during bootstrapping. A somewhat simple solution for components running as part of the same process is to use a fake client, e.g., <code>sigs.k8s.io/controller-runtime/pkg/client/fake</code> or <code>github.com/gardener/gardener/pkg/client/kubernetes/fake</code>. Those fake clients, which are usually used for unit testing, can be utilized to create the necessary resources in memory without a real API server. It allows to simulate/fake the API server until the real one becomes available.</p><p>In the <code>gardenadm init</code> flow, the initial application of the <code>OperatingSystemConfig</code> by components of the <code>gardener-node-agent</code> is an example of this. The <code>gardener-node-agent</code> retrieves the <code>OperatingSystemConfig</code> from a <code>Secret</code>. Furthermore, it also checks its local <code>Node</code> resource. Both are not available until after the control plane starts running. Therefore, a fake client is useful for bootstrapping.</p><p>Another example is the deployment of the extensions. The existing implementation requires a garden cluster with <code>Controller{Registration,Deployment}</code> resources to apply <code>ControllerInstallation</code>s. However, this also works with the fake client so that extensions can be deployed during bootstrapping.</p><h6 id="host-network-vs-pod-network" tabindex="-1">Host Network vs. Pod Network <a class="header-anchor" href="#host-network-vs-pod-network" aria-label="Permalink to &quot;Host Network vs. Pod Network&quot;">​</a></h6><p>Typically, the <code>gardener-resource-manager</code> is always deployed in the pod network. The same is true for the Gardener extensions.</p><p>In general, it is desirable to be able to use the pod network as it offers a better separation and less potential for clashes, e.g., with regards to port reuse. Components most likely need to be adapted to make some ports configurable so that they do not clash, e.g., metrics and webhooks ports of extensions. During bootstrapping, the circular dependencies between the components makes it impossible to start with the pod network.</p><p>It is obvious, that the networking extension, which should create the manifests to be used to create a working pod network, can initially not run in the pod network itself. As <code>gardener-resource-manager</code> is utilized to deploy the manifests via a <code>ManagedResource</code>, it cannot run in the pod network initially either.</p><p>Once the pod network is established, theses components can be restarted in the pod network.</p><h6 id="dealing-with-webhooks-for-control-plane-components" tabindex="-1">Dealing with Webhooks for Control Plane Components <a class="header-anchor" href="#dealing-with-webhooks-for-control-plane-components" aria-label="Permalink to &quot;Dealing with Webhooks for Control Plane Components&quot;">​</a></h6><p>The minimal standard Kubernetes control plane components (<code>etcd</code>, <code>kube-apiserver</code>, <code>kube-controller-manager</code>, <code>kube-scheduler</code>) run as static pods in this setup. However, some extensions might want to mutate them <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/controlplane-webhooks.md" target="_blank" rel="noreferrer">via webhooks</a>. Previously, this was done by mutating the <code>Deployment</code>/<code>StatefulSet</code> of the components. With static pods, those resources do not exist, though.</p><p>To make it possible to use webhooks as before, we propose to create dummy <code>Deployment</code>/<code>StatefulSet</code> resources for the control plane components with <code>replicas=0</code>. These resources will be watched and updates will be translated to the manifests of the static pods. The manifests are then rolled out via the <code>OperatingSystemConfig</code> applied by <code>gardener-node-agent</code>.</p><h6 id="etcd-management-via-etcd-druid" tabindex="-1"><code>etcd</code> Management via <a href="https://github.com/gardener/etcd-druid" target="_blank" rel="noreferrer"><code>etcd-druid</code></a> <a class="header-anchor" href="#etcd-management-via-etcd-druid" aria-label="Permalink to &quot;`etcd` Management via [`etcd-druid`](https://github.com/gardener/etcd-druid)&quot;">​</a></h6><p>Gardener itself will only be capable of running a minimal deployment of <code>etcd</code> for the bootstrapping process (i.e., no <a href="https://github.com/gardener/etcd-backup-restore" target="_blank" rel="noreferrer"><code>backup-restore</code></a> sidecar or any sophisticated configuration for running <code>etcd</code> productively). After the initial bootstrapping has been completed, we would like to leverage what has already been implemented in Gardener&#39;s <code>etcd</code> operator, <code>etcd-druid</code>, for the management of <code>etcd</code> clusters (including backup &amp; restore functionality, data compaction, and more).</p><p>The idea is to deploy <code>etcd-druid</code> into the cluster, and create a corresponding <code>druid.gardener.cloud/v1alpha1.Etcd</code> resource. As part of its reconciliation, <code>etcd-druid</code> typically generates a <code>StatefulSet</code>. In this scenario, it can still do that, though it should set the <code>replicas=0</code>. Perhaps it&#39;s even easier to create dedicated <code>StatefulSet</code>s for multi-node <code>etcd</code> clusters. This way, they can be easily translated into static pods and distributed to the respective control plane nodes. The static pod manifest can then be exchanged on the host and replace the &quot;bootstrap <code>etcd</code>&quot; with the &quot;productive <code>etcd</code>&quot; generated by <code>etcd-druid</code> whilst reusing the same data directory.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>At the time of writing this GEP, it is not yet fully clear how/whether this approach fits into the design plans for <code>etcd-druid</code>. An alternative idea is to make <code>etcd-druid</code> aware of the concept of self-hosted shoot clusters and give it further control into the management of static <code>etcd</code> pods. The details are still subject to discussion and will become clearer in the future. Since we need a &quot;bootstrap <code>etcd</code>&quot; anyway to get the cluster up and running, we can proceed with this GEP and its implementation in parallel while the discussion around how <code>etcd-druid</code> can take over the management is ongoing.</p></div><h4 id="gardenadm-token" tabindex="-1"><code>gardenadm token</code> <a class="header-anchor" href="#gardenadm-token" aria-label="Permalink to &quot;`gardenadm token`&quot;">​</a></h4><p>After the first control plane node has been bootstrapped, it is very likely that we want to join additional nodes (either more control plane nodes to achieve high-availability, or worker nodes). As for regular shoot clusters, we will leverage the <a href="https://kubernetes.io/docs/reference/access-authn-authz/kubelet-tls-bootstrapping/" target="_blank" rel="noreferrer"><code>kubelet</code> TLS bootstrapping</a> process. This means that a <a href="https://kubernetes.io/docs/reference/access-authn-authz/bootstrap-tokens/" target="_blank" rel="noreferrer">bootstrap token</a> is used by <code>kubelet</code> to request a client certificate via the <code>CertificateSigningRequest</code> API.</p><p>We will provide commands to create and manage such bootstrap tokens:</p><ul><li><code>gardenadm token generate</code> will generate a random bootstrap token.</li><li><code>gardenadm token create [token]</code> will create a bootstrap token on the server. If no <code>[token]</code> is provided, the command will generate a random token instead.</li><li><code>gardenadm token delete [token-id]</code> will delete a bootstrap token.</li><li><code>gardenadm token list</code> will list all bootstrap tokens on the server.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>kubeadm</code> goes one step further and implements a discovery process for the certificate authority of the control plane. For this purpose, so-called &quot;discovery tokens&quot; are used.</p><p>First, the CA certificate is retrieved via an insecure connection from a <code>ConfigMap</code> that got created as part of the <code>kubeadm init</code> process. Next, the downloaded CA certificate is validated based on a hash of the public key that must be provided as part of <code>kubeadm join</code>. Finally, as additional validation, the CA certificate is retrieved via secure connection and compared with the CA retrieved initially.</p><p>We might implement a similar discovery mechanism for <code>gardenadm</code> as this project evolves. However, we plan to first focus on the other, &quot;more functional&quot; aspects.</p></div><h4 id="gardenadm-join" tabindex="-1"><code>gardenadm join</code> <a class="header-anchor" href="#gardenadm-join" aria-label="Permalink to &quot;`gardenadm join`&quot;">​</a></h4><p>Joining additional worker nodes is very similar to how it works for regular shoot clusters. This command instruments <code>gardener-node-agent</code> reconciliation logic to write the <code>systemd</code> units and needed files for the <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/node-agent.md#installation-and-bootstrapping" target="_blank" rel="noreferrer"><code>gardener-node-init</code></a> component onto the disk of the machine. When this unit is started, it extracts the <code>gardener-node-agent</code> binary from its container image, and creates the <code>systemd</code> unit for it. <code>gardener-node-agent</code> will then use the provided bootstrap token to fetch the <code>OperatingSystemConfig</code> from a <code>Secret</code> residing in the <code>kube-system</code> namespace of the cluster. This <code>OperatingSystemConfig</code> contains the actual components like <code>kubelet</code>, <code>valitail</code>, etc. With the help of the same bootstrap token, <code>kubelet</code> will come up and register its <code>Node</code> resource, hence, successfully joins the cluster.</p><p>The process for joining additional control plane nodes is very similar. The main difference is that the <code>OperatingSystemConfig</code> will contain the manifests of the static pods for the minimal standard Kubernetes control plane. Depending on the <code>etcd</code> management, it may be necessary to have individual <code>OperatingSystemConfig</code>s for each control plane node. However, this is not yet fully clear and needs further investigation (see <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#etcd-management-via-etcd-druid"><code>etcd</code> Management via <code>etcd-druid</code></a>). Apart from this, <code>etcd</code> also needs to be re-configured to have the new node join the <code>etcd</code> cluster.</p><h4 id="gardenadm-connect" tabindex="-1"><code>gardenadm connect</code> <a class="header-anchor" href="#gardenadm-connect" aria-label="Permalink to &quot;`gardenadm connect`&quot;">​</a></h4><p>This command deploys a <code>gardenlet</code> into the self-hosted shoot cluster and connects it to an existing garden cluster. As part of this operation, the corresponding <code>Shoot</code> resource will be created in the garden cluster. Afterwards, the <code>gardenlet</code> will reconcile the self-hosted shoot cluster similarly to regular shoot clusters.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>When there is no existing Gardener system yet (for example, because the created self-hosted shoot cluster is the initial cluster), then <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/operator.md" target="_blank" rel="noreferrer"><code>gardener-operator</code></a> must be deployed first, and the <a href="https://github.com/gardener/gardener/tree/master/example/operator/20-garden.yaml" target="_blank" rel="noreferrer"><code>Garden</code></a> must be created, before the <code>gardenlet</code> can be deployed.</p><p>Also, it is not yet clear whether the existing <code>gardenlet</code> binary will be re-used, or whether we better create a dedicated, new binary with slimmed down functionality catered for only managing self-hosted shoot clusters.</p></div><p>Depending on the scenario, a self-hosted shoot cluster may be air-gapped for periods of time. Therefore, please note that the cluster should function also when air-gapped/when it has limited or no network connectivity. Updates can not be performed during that time, but ordinary operations with the cluster itself (e.g., creating pods or services) should still be possible. It is important that the <a href="https://github.com/gardener/gardener/tree/master/docs/deployment/version_skew_policy.md" target="_blank" rel="noreferrer">version skew</a> is always respected.</p><h4 id="gardenadm-version" tabindex="-1"><code>gardenadm version</code> <a class="header-anchor" href="#gardenadm-version" aria-label="Permalink to &quot;`gardenadm version`&quot;">​</a></h4><p>This command prints the version of <code>gardenadm</code>.</p><h3 id="shoot-api" tabindex="-1"><code>Shoot</code> API <a class="header-anchor" href="#shoot-api" aria-label="Permalink to &quot;`Shoot` API&quot;">​</a></h3><p>We need some mechanism to distinguish regular shoot clusters from self-hosted shoot clusters. As the most prominent difference is that there are dedicated machines for the control plane components, we propose to notice the difference based on the existence of a worker pool for the control plane:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">control-plane</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      controlPlane</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span></code></pre></div><p>An alternative is to augment <code>.spec.controlPlane</code> with this information, however, we think adding a dedicated worker pool is the better and more natural fit (we need it anyways to enable re-use of most of the existing code).</p><h3 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h3><p>We distinguish between two different scenarios (for now):</p><ul><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#unmanaged-infrastructure">Unmanaged Infrastructure</a>, meaning that there is no programmable infrastructure available. We consider this the &quot;bare metal&quot; or &quot;edge&quot; use-case, where at first machines must be (often manually) prepared by human operators. In this case, network setup (e.g., VPCs, subnets, route tables, etc.) and machine management are out of scope.</li><li><a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#managed-infrastructure">Managed Infrastructure</a>, meaning that there is programmable infrastructure available where we can leverage <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/README.md#infrastructure-provider" target="_blank" rel="noreferrer">provider extensions</a> and <a href="https://github.com/gardener/machine-controller-manager" target="_blank" rel="noreferrer"><code>machine-controller-manager</code></a> in order to manage the network setup and the machines.</li></ul><p>The general procedure of bootstrapping a self-hosted shoot cluster is similar in both scenarios.</p><h4 id="unmanaged-infrastructure" tabindex="-1">Unmanaged Infrastructure <a class="header-anchor" href="#unmanaged-infrastructure" aria-label="Permalink to &quot;Unmanaged Infrastructure&quot;">​</a></h4><p>In this scenario, the starting point is right on the first machine that shall be transformed into a control plane node. It is assumed that the network was set up properly (see <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#prerequisites">Prerequisites</a>). Since machine management is out of scope, upgrades requiring to roll out the nodes (e.g., Kubernetes version upgrades, operating system upgrades, CA rotation, <a href="https://github.com/gardener/gardener/tree/master/docs/usage/shoot_updates.md#rolling-update-triggers" target="_blank" rel="noreferrer">see more</a>) must be performed in-place. We will leverage the functionality that is to be developed in the scope of <a href="https://github.com/gardener/gardener/issues/10219" target="_blank" rel="noreferrer">#10219</a>. This will also include operating system upgrades <a href="https://github.com/gardener/gardener/issues/10219#issuecomment-2262299606" target="_blank" rel="noreferrer">planned for Garden Linux</a>.</p><h4 id="managed-infrastructure" tabindex="-1">Managed Infrastructure <a class="header-anchor" href="#managed-infrastructure" aria-label="Permalink to &quot;Managed Infrastructure&quot;">​</a></h4><p>In this scenario, we can leverage the existing <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/resources/infrastructure.md" target="_blank" rel="noreferrer"><code>extensions.gardener.cloud/v1alpha1.Infrastructure</code> API</a> in order to let the respective provider extension generate the necessary network resources (VPCs, subnets, etc., whatever is needed for the respective infrastructure). <code>machine-controller-manager</code> can be used to create the control plane nodes (and later also the worker nodes) of the self-hosted shoot cluster.</p><p>The challenge is that both Gardener provider extensions and <code>machine-controller-manager</code> depend on a pre-existing Kubernetes cluster or in general an API server. Hence, we propose to use a <a href="https://kind.sigs.k8s.io" target="_blank" rel="noreferrer">KinD cluster</a>, deploy the needed components into it, and create the necessary <code>Infrastructure</code>, <code>MachineClass</code>, and <code>MachineDeployment</code> resources. This way, these components can be reused as-is, without big changes or re-wiring of these complex components to run in-process with a fake client (as we do during the <code>gardenadm init</code> flow for the simpler components). Once the controllers have reconciled successfully, we can export the created infrastructure state and the <code>Machine</code> resources, bootstrap the self-hosted shoot cluster similar to the <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#commands">general flow</a> also needed for the <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#unmanaged-infrastructure">Unmanaged Infrastructure scenario</a>, and import the state again into the created cluster.</p><p>There is no special assumption about the location of the KinD cluster. It should run somewhere where it can access the API of the target infrastructure. In a public cloud environment, that means anywhere with internet access. In a private cloud environment, e.g. with OpenStack, the KinD cluster should be in a network being able to access the corresponding API, e.g., by being in the same infrastructure or having a VPN tunnel. It can run on the laptop of the operator if the network connectivity is ensured, or it could be a virtual machine next to the target.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Since worker node management will be taken over by <code>machine-controller-manager</code>, <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#commands">step 4</a> (joining worker nodes) from above list can be omitted. <code>machine-controller-manager</code> will also take over the creation of the control plane nodes, however, bootstrapping and joining them must still be performed by the user (meaning that <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#commands">step 3</a> remains). It still needs to be investigated how much automation by <code>machine-controller-manager</code> is possible for the control plane nodes. As bootstrapping/joining of control plane nodes is a manual process for now, <code>machine-controller-manager</code> should not roll control plane nodes automatically.</p></div><p>Since we assume that this scenario will be the prominent one, we plan to add another command, <code>gardenadm bootstrap</code>, which shall simplify these steps.</p><h5 id="gardenadm-bootstrap" tabindex="-1"><code>gardenadm bootstrap</code> <a class="header-anchor" href="#gardenadm-bootstrap" aria-label="Permalink to &quot;`gardenadm bootstrap`&quot;">​</a></h5><p>This command creates the virtual network and machines to be used for the control plane of the self-hosted shoot cluster. It uses an existing KinD cluster to temporarily deploy existing Gardener components (unaware of the self-hosted shoot cluster use-case). These components, such as provider extensions and <code>machine-controller-manager</code>, are used to create the necessary infrastructure and machines.</p><p>The high-level steps are as follows:</p><ol><li>Deploy <code>gardener-resource-manager</code> to be able to create provider extensions.</li><li>Deploy the required provider extension.</li><li>Apply the <code>Infrastructure</code> resource to create the virtual network.</li><li>Deploy <code>machine-controller-manager</code> to be able to create the machines.</li><li>Apply the <code>Worker</code> resource to create the control plane nodes.</li><li>Wait for the machines to be created.</li><li>Stop <code>machine-controller-manager</code> to prevent deletion of the machines as they will not become ready since there is no Kubernetes cluster yet to join.</li><li>Create a <code>Bastion</code> resource to be able to access the machines and execute <code>gardenadm init</code> (can be later optimized via <code>cloud-init</code> through a cloud config that invokes <code>gardenadm init</code> directly when creating the machines).</li></ol><p>The states of the <code>Infrastructure</code> and <code>Machine</code> resources need to be exported from the KinD cluster. Once the self-hosted shoot cluster control plane is running, the state should be imported so that it can be managed by the provider extension and <code>machine-controller-manager</code> respectively.</p><p>The KinD cluster can be deleted afterwards.</p><h3 id="disaster-recovery" tabindex="-1">Disaster Recovery <a class="header-anchor" href="#disaster-recovery" aria-label="Permalink to &quot;Disaster Recovery&quot;">​</a></h3><p>Disasters can strike in many different ways. This section discusses disasters in ascending order of severity. Some scenarios can be handled by self-hosted shoot clusters automatically, others require manual intervention.</p><h4 id="single-node-failure" tabindex="-1">Single-Node Failure <a class="header-anchor" href="#single-node-failure" aria-label="Permalink to &quot;Single-Node Failure&quot;">​</a></h4><p>The simplest of failures is the outage of a single control plane node, e.g., due to a power outage. Assuming no damage from the outage itself, the node should start up again and resume operation automatically once the outage has been resolved. As the <code>kubelet</code> is installed as a systemd service, it will automatically run after a reboot and start the static pods for the control plane components. Assuming there is no hard disk failure, <code>etcd</code> will recover after restart and continue serving the cluster.</p><p>In case the local <code>etcd</code> data is corrupt after the outage, it is assumed that the <code>backup-restore</code> sidecar restores the last backup automatically for non-HA clusters. If the cluster is set up in HA mode, i.e., with at least three control plane nodes, the local <code>etcd</code> instance may learn new changes from its peers afterwards.</p><p>A hard disk failure requires manual intervention as the disk needs to be replaced anyway. The node needs to be bootstrapped again, and the <code>etcd</code> data needs to be restored from a backup. If the affected node was part of a highly available control plane, the bootstrapping process may be simplified via <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-join"><code>gardenadm join</code></a>.</p><p>The effect of a single node failure on the cluster depends on whether the control plane is highly available or not. If the control plane consists only of the single node, the control plane is not available during the outage. In case the control plane consists of at least three nodes, i.e., is highly available, the control plane remains available during the outage with only minor disruptions, i.e., loss of existing connections.</p><h4 id="multi-node-failure" tabindex="-1">Multi-Node Failure <a class="header-anchor" href="#multi-node-failure" aria-label="Permalink to &quot;Multi-Node Failure&quot;">​</a></h4><p>Multi-node failures are only relevant to highly available control planes as otherwise there is only a single control plane node.</p><p>Simple failures, e.g., due to power outages, can be handled as described in the <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#single-node-failure">Single-Node Failure</a> section. Even with multiple nodes restarting, we assume that <code>etcd</code> will eventually reach a quorum again and fully recover.</p><p>However, if the hard disks of multiple nodes fail around the same point in time, <code>etcd</code> looses quorum (permanently) and may need manual intervention to restore it. In the worst case, the entire control plane must be manually re-bootstrapped (running <code>gardenadm init</code> again) on new or fresh machines whilst providing the latest available backup.</p><p>Apart from transient failures such as power outages, multi-node failures usually result in the complete unavailability of the control plane.</p><h4 id="data-center-failure" tabindex="-1">Data Center Failure <a class="header-anchor" href="#data-center-failure" aria-label="Permalink to &quot;Data Center Failure&quot;">​</a></h4><p>If the whole data center fails catastrophically, manual intervention is always required. While <code>etcd</code> backups are hopefully replicated to a second site, restoring the control plane nodes requires similar manual effort as mentioned above.</p><p>The resolution/handling of data center failures is out of scope of this GEP.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><h3 id="self-hosted-shoot-clusters-for-end-users" tabindex="-1">Self-Hosted Shoot Clusters for End-Users <a class="header-anchor" href="#self-hosted-shoot-clusters-for-end-users" aria-label="Permalink to &quot;Self-Hosted Shoot Clusters for End-Users&quot;">​</a></h3><p>As implicitly mentioned in the <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#non-goals">Non-Goals</a> section, the focus of this GEP is to allow Gardener operators to create self-hosted shoot clusters. However, the creation of such clusters by end-users is not covered by this GEP. This could become a future topic if we consider it relevant enough.</p><p>Handling creation of self-hosted shoot clusters by end-users requires refined access controls for the <code>gardenlet</code>. Currently, the <code>gardenlet</code> runs as part of a seed cluster and has access to some resources, which are not accessible to end-users but only to operators. An example resource is the <code>ControllerDeployment</code>, which may contain credentials, e.g., for certificate management or domain name services. In case this scenario is desired and the security boundary between Gardener operators and end-users should stay as is, the extension deployment needs to be adapted.</p><p>While it may be appealing to have support for self-hosted shoot cluster for end-users, it is important to understand that this feature may complicate the world for both operators and end-users. The benefits of self-hosted shoot clusters for the garden runtime cluster and/or soil clusters, i.e., unmanaged seed clusters, is fairly obvious: It allows to create a Gardener landscape without external dependency to a Kubernetes service provider. However, the benefits for end-users are less clear (except for the mentioned edge/on-prem/air-gapped use cases). It needs to be carefully considered and documented for what scenarios self-hosted shoot clusters are the right choice, and when ordinary shoot clusters with their control plane running on a seed cluster are the better way to go. Without this consideration, the feature may increase the operational complexity for Gardener operators, and the cognitive load for end-users.</p><h3 id="network-connectivity-to-garden-cluster" tabindex="-1">Network Connectivity to Garden Cluster <a class="header-anchor" href="#network-connectivity-to-garden-cluster" aria-label="Permalink to &quot;Network Connectivity to Garden Cluster&quot;">​</a></h3><p>Another aspect that was only barely touched in this GEP is the reliability of the network connectivity between the self-hosted shoot cluster and Gardener. In the <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-connect"><code>gardenadm connect</code> section</a>, it was mentioned that the cluster should function also when air-gapped/when it has limited or no network connectivity. However, we are deliberately vague what &quot;limited network connectivity&quot; means. Detailing this aspect out can be considered future work. As mentioned in the corresponding section, the <a href="https://github.com/gardener/gardener/tree/master/docs/deployment/version_skew_policy.md" target="_blank" rel="noreferrer">version skew</a> plays an important role in this context, determining the maximum time the self-hosted shoot cluster can be disconnected from Gardener. Long term support of Gardener and associated components may also be considered future work.</p><h3 id="changes-to-shoot-components" tabindex="-1">Changes to Shoot Components <a class="header-anchor" href="#changes-to-shoot-components" aria-label="Permalink to &quot;Changes to Shoot Components&quot;">​</a></h3><p>Due to the changed network layout of self-hosted shoot clusters, the usage of some shoot components needs to be reconsidered. Examples are the VPN connection between control plane and data plane, the <code>apiserver-proxy</code> and the way metrics are scraped. This GEP does not cover these changes in detail, but they are important to be considered when implementing it. The following examples are just used to illustrate the need for changes, but are not meant to be exhaustive:</p><ul><li><p>The VPN connection between control plane and data plane is not needed anymore as the control plane runs on the same network as the data plane. Previously, the VPN connection was used to secure the communication between the control plane and the data plane. This was important as the control plane and the data plane were running in different networks with a potentially untrusted network in between. In the self-hosted shoot cluster scenario, this is no longer the case. The control plane can directly communicate with the data plane without the need for a VPN connection.</p></li><li><p>The <code>apiserver-proxy</code> (see <a href="https://github.com/gardener/enhancements/blob/main/geps/0028-self-hosted-shoot-clusters/11-apiserver-network-proxy.md" target="_blank" rel="noreferrer">GEP-11</a> for details) is used to forward requests from the data plane directed at <code>kubernetes.default.svc.cluster.local</code> to the control plane. In the self-hosted shoot cluster scenario, this can be simplified by directly pointing <code>kubernetes.default.svc.cluster.local</code> to the actual endpoints of the <code>kube-apiserver</code>. This way, the <code>apiserver-proxy</code> is no longer needed. Another aspect is the <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/resource-manager.md#kubernetes-service-host-injection" target="_blank" rel="noreferrer">mutating webhook for injecting the <code>KUBERNETES_SERVICE_HOST</code> environment variable</a>, which can be disabled in the self-hosted shoot cluster scenario as well.</p></li><li><p>In ordinary shoot clusters, the metrics of components running in the data plane are scraped indirectly via the <code>kube-apiserver</code>. This allows the observability stack to use the VPN connection without explicitly configuring it. As stated above, the VPN connection is no longer needed in the self-hosted shoot cluster scenario. Therefore, the observability stack could also directly scrape metrics from the data plane components instead of going through the <code>kube-apiserver</code>.</p></li></ul><p>There may be other components, which are affected by the changed network layout and need to be adapted.</p><h3 id="air-gapped-gardener-landscapes" tabindex="-1">Air-Gapped Gardener Landscapes <a class="header-anchor" href="#air-gapped-gardener-landscapes" aria-label="Permalink to &quot;Air-Gapped Gardener Landscapes&quot;">​</a></h3><p>While it is already possible today to run a Gardener landscape in an air-gapped environment, the self-hosted shoot cluster feature will make it easier to set up such a landscape. This is due to the fact that it removes the dependency on an external Kubernetes cluster to run the Garden and act as the initial seed cluster. Therefore, it may be worthwhile to take a closer look at the requirements for air-gapped Gardener landscapes and document them properly.</p><p>Topics to consider (without any claim of completeness) are:</p><ul><li>OCI container registry for providing container images/binaries</li><li>Configuration of image vector overrides to consume only local images/binaries</li><li>Local DNS configuration for managing Gardener landscape domains</li><li>TLS certificate handling, e.g. for connections between components, but also for authentication</li></ul><p>The goal would be to provide a comprehensive guide on how to set up an air-gapped Gardener landscape, which can be applied on various infrastructures. It may also be useful for scenarios that are not fully air-gapped, but only desire selected parts of the sovereignty this provides.</p><h3 id="scaling-the-control-plane-of-self-hosted-shoot-clusters" tabindex="-1">Scaling the Control Plane of Self-Hosted Shoot Clusters <a class="header-anchor" href="#scaling-the-control-plane-of-self-hosted-shoot-clusters" aria-label="Permalink to &quot;Scaling the Control Plane of Self-Hosted Shoot Clusters&quot;">​</a></h3><p>The control plane components of ordinary Gardener shoot clusters are scaled horizontally and vertically in various ways. Autoscaling is not covered in this GEP, but it is important in the long run to ensure efficient resource usage.</p><p>As far as this GEP is concerned, the control plane of self-hosted shoot clusters is scaled horizontally by adding more control plane nodes (see <a href="/docs/proposals/0028-self-hosted-shoot-clusters/readme/#gardenadm-join"><code>gardenadm join</code></a>).</p><p>This approach can be problematic in various ways. As this GEP proposes to always deploy the full set of default control plane components on each control plane node, there may be more instances running for <code>kube-scheduler</code> and <code>kube-controller-manager</code> than practically necessary. While this may be a good approach in scaling <code>kube-apiserver</code> horizontally, it may cause additional synchronisation overhead for <code>etcd</code> where having more <code>etcd</code> cluster members automatically also means more replication. Furthermore, from <code>etcd</code>&#39;s perspective the amount of control plane nodes should ideally be odd and no more than seven (see <a href="https://etcd.io/docs/v3.4/faq/" target="_blank" rel="noreferrer">etcd faq</a>). This further limits the scalability of the control plane.</p><p>Therefore, it may be a good idea to investigate how node roles can help improve efficiency in a scale-out self-hosted shoot cluster scenario. Some control plane nodes could include the full set of default control plane components while others may use a reduced set of components. This could be achieved by having roles for either individual components or different set of components.</p><p>An alternative solution would be to expand for example <code>kube-apiserver</code> beyond the control plane nodes, i.e. deploy additional instances on ordinary worker nodes. This could provide true scaling via deployments with ordinary horizontal/vertical pod autoscaling, but it would remove the strict separation between control and data plane nodes.</p><p>Yet another option in the contrary direction would be to allow non-control plane workloads to be deployed to control plane nodes. This would allow to use the control plane nodes to their full capacity, but it would also blur the separation between control and data plane nodes. While it may improve the resource utilisation of control plane nodes, it may also introduce security risks.</p><p>In any case, revisiting the scaling problem is required to ensure efficient resource usage with growing control plane usage in the context of self-hosted shoot clusters.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><h3 id="using-existing-tools" tabindex="-1">Using Existing Tools <a class="header-anchor" href="#using-existing-tools" aria-label="Permalink to &quot;Using Existing Tools&quot;">​</a></h3><p>Existing tools, e.g., <a href="https://k3s.io" target="_blank" rel="noreferrer"><code>k3s</code></a> or <a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm" target="_blank" rel="noreferrer"><code>kubeadm</code></a>, could be used to create the initial Kubernetes cluster. This cluster could then be &quot;adopted&quot; by Gardener and managed by the <code>gardenlet</code> as described for the day-2 operations in the self-hosted shoot cluster case. It was deemed much more complex to align a cluster created by a third-party tool with Gardener&#39;s expectations than to create the cluster directly with Gardener. The fact that these tools evolve independently from Gardener and may introduce breaking changes was another reason to prefer the direct creation with Gardener.</p><h3 id="using-existing-services" tabindex="-1">Using Existing Services <a class="header-anchor" href="#using-existing-services" aria-label="Permalink to &quot;Using Existing Services&quot;">​</a></h3><p>Existing services, e.g., <a href="https://aws.amazon.com/eks" target="_blank" rel="noreferrer">AWS EKS</a>, <a href="https://azure.microsoft.com/en-us/services/kubernetes-service" target="_blank" rel="noreferrer">Azure AKS</a>, or <a href="https://cloud.google.com/kubernetes-engine" target="_blank" rel="noreferrer">Google GKE</a>, could be used to create the initial Kubernetes cluster. As these services are managed, it is not possible to &quot;adopt&quot; the cluster and manage its control plane. Furthermore, this approach is limited in where it can be used. For example, it may be undesirable/impossible for an air-gapped environment to have a dependency to a cloud provider.</p><h3 id="using-existing-gardener" tabindex="-1">Using Existing Gardener <a class="header-anchor" href="#using-existing-gardener" aria-label="Permalink to &quot;Using Existing Gardener&quot;">​</a></h3><p>Using an existing Gardener to create a self-hosred cluster is an option, yet it requires a more complex satisfaction of prerequisites to make this approach work. For example, network connectivity from a seed cluster (where extensions and a <code>gardenlet</code> runs) to the target infrastructure must exist. When the initial cluster shall be created, pivoting from a local KinD cluster can be an option, but it also requires to solve the challenge of migrating the Gardener control plane. In summary, we considered this approach more complex to develop and use.</p>',137)]))}const g=t(n,[["render",i]]);export{f as __pageData,g as default};
